let urlDateFrom = $derived(getValidDate($page.url.searchParams.get('dateFrom')));
let urlDateTo = $derived(getValidDate($page.url.searchParams.get('dateTo')));

// Client-side filters - temporary values for inputs
let tempFilterDateFrom = $state(getValidDate($page.url.searchParams.get('dateFrom')));
let tempFilterDateTo = $state(getValidDate($page.url.searchParams.get('dateTo')));
let tempFilterMerchant = $state('');
let tempFilterAmountMin = $state('');
let tempFilterAmountMax = $state('');

