export async function getSignedReceiptUrl(
	path: string | null | undefined,
	expiresIn: number = DEFAULT_EXPIRY_SECONDS
): Promise<string | null> {
	if (!path) return null;

	const { data, error } = await supabase.storage.from('receipts').createSignedUrl(path, expiresIn);

