/**
 * #{#sec1b} Signed URL Utility
 *
 * Centralizes signed URL generation for the receipts storage bucket.
 * Replaces all getPublicUrl() calls with time-limited signed URLs.
 */

import { supabase } from '$lib/supabaseClient';

/** Default signed URL expiry: 1 hour */
const DEFAULT_EXPIRY_SECONDS = 3600;

/**
 * Generate a signed URL for a file in the receipts storage bucket.
 *
 * @param path - Storage path (e.g. "user-id/filename.jpg")
 * @param expiresIn - URL lifetime in seconds (default: 3600)
 * @returns Signed URL string, or null if path is empty or generation fails
 */
export async function getSignedReceiptUrl(
	path: string | null | undefined,
	expiresIn: number = DEFAULT_EXPIRY_SECONDS
): Promise<string | null> {
	if (!path) return null;

	const { data, error } = await supabase.storage.from('receipts').createSignedUrl(path, expiresIn);

	if (error) {
		console.error('Failed to create signed URL for path:', path, 'error:', error.message);
		return null;
	}

	return data.signedUrl;
}

