import { describe, it, expect, vi } from 'vitest';
import { collectSignedUrls, type BatchSigner, type SignedUrlResult } from './signedUrlBatch';

/** Typed fake signer: returns a signed URL for any path present in `urls`, else a per-item error. */
function fakeSigner(urls: Record<string, string>): BatchSigner {
	return async (paths: string[]): Promise<SignedUrlResult[]> =>
		paths.map((p) => ({
			path: p,
			signedUrl: urls[p] ?? null,
			error: urls[p] ? null : 'not found'
		}));
}

describe('collectSignedUrls', () => {
	it('maps each path to its signed URL', async () => {
		const sign = fakeSigner({ 'a.jpg': 'https://x/a', 'b.jpg': 'https://x/b' });
		const result = await collectSignedUrls(['a.jpg', 'b.jpg'], sign);
		expect(result).toEqual({ 'a.jpg': 'https://x/a', 'b.jpg': 'https://x/b' });
	});

	it('dedupes repeated paths and drops falsy ones before signing', async () => {
		const sign = vi.fn(fakeSigner({ 'a.jpg': 'https://x/a' }));
		const result = await collectSignedUrls(['a.jpg', 'a.jpg', '', 'a.jpg'], sign);
		expect(result).toEqual({ 'a.jpg': 'https://x/a' });
		// Only the single unique, non-empty path is sent to the signer.
		expect(sign).toHaveBeenCalledTimes(1);
		expect(sign).toHaveBeenCalledWith(['a.jpg']);
	});

	it('chunks paths into batches of the given size', async () => {
		const urls: Record<string, string> = {};
		const paths: string[] = [];
		for (let i = 0; i < 201; i++) {
			paths.push(`p${i}.jpg`);
			urls[`p${i}.jpg`] = `https://x/p${i}`;
		}
		const sign = vi.fn(fakeSigner(urls));
		const result = await collectSignedUrls(paths, sign, 200);
		expect(sign).toHaveBeenCalledTimes(2); // 200 + 1
		expect(Object.keys(result)).toHaveLength(201);
	});

	it('drops only the paths whose items carry an error or null URL', async () => {
		const sign = fakeSigner({ 'ok.jpg': 'https://x/ok' }); // missing.jpg has no URL → error
		const result = await collectSignedUrls(['ok.jpg', 'missing.jpg'], sign);
		expect(result).toEqual({ 'ok.jpg': 'https://x/ok' });
	});

	it('soft-fails a rejecting chunk without dropping other chunks, never throwing', async () => {
		const good = fakeSigner({ 'g0.jpg': 'https://x/g0', 'g1.jpg': 'https://x/g1' });
		// Batch size 1 → two chunks; the second chunk's signer call rejects.
		const sign: BatchSigner = vi.fn(async (paths) => {
			if (paths[0] === 'bad.jpg') throw new Error('storage down');
			return good(paths);
		});
		const result = await collectSignedUrls(['g0.jpg', 'bad.jpg'], sign, 1);
		expect(result).toEqual({ 'g0.jpg': 'https://x/g0' });
	});

	it('returns an empty map and signs nothing for empty input', async () => {
		const sign = vi.fn(fakeSigner({}));
		const result = await collectSignedUrls([], sign);
		expect(result).toEqual({});
		expect(sign).not.toHaveBeenCalled();
	});
});

